/* module: src_js/core/ajax.js */
/**
 * Ermac AJAX: a minimal promise-based XMLHttpRequest wrapper,
 * keeping cross-domain credentials and abortability of the old jQuery $.ajax calls.
 *
 * Returns a promise, additionally fitted with an .abort() method.
 * The promise resolves with the parsed response, or rejects with
 * {aborted: true} for requests cancelled via .abort(), or {status: N}
 * otherwise; NB a network failure (offline, refused, CORS) is status 0
 * but NOT an abort: like jQuery's textStatus 'error' vs 'abort'.
 */

function ajax(settings) {
  const xhr = new XMLHttpRequest();
  let aborted = false;
  let url = settings.url;
  const type = (settings.type || 'GET').toUpperCase();
  let query = null;

  if (settings.data) {
    if (type === 'GET') {
      url += (url.indexOf('?') === -1 ? '?' : '&') + param(settings.data);
    } else {
      query = param(settings.data);
    }
  }

  const promise = new Promise(function (resolve, reject) {
    xhr.onreadystatechange = function () {
      if (xhr.readyState !== 4) return;
      if (xhr.status === 0) return reject({ aborted: aborted, status: 0, xhr: xhr });
      if (xhr.status >= 200 && xhr.status < 300) {
        let answer = xhr.responseText;
        if (
          settings.dataType === 'json' ||
          (settings.dataType !== 'text' &&
            (xhr.getResponseHeader('Content-Type') || '').indexOf('json') !==
              -1)
        ) {
          try {
            answer = JSON.parse(answer);
          } catch (e) {
            /* keep raw text */
          }
        }
        resolve(answer);
      } else {
        reject({ status: xhr.status, xhr: xhr });
      }
    };
    xhr.open(type, url);
    xhr.withCredentials = true;
    if (type === 'POST' && query) {
      xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
    }
    xhr.send(query);
  });

  promise.abort = function () {
    aborted = true;
    try {
      xhr.abort();
    } catch (e) {}
  };
  return promise;
}

/**
 * URL query serialization, mimicking the vendored jQuery 3.7.1 $.param()
 * (traditional = false) exactly: encodeURIComponent per key/value, null and
 * undefined emitted as "key=", function values called, nested values
 * expanded like jQuery's buildParams(): arrays as key[]= (key[i]= for
 * object/array members), objects as key[name]=, a top-level array as
 * {name, value} pairs.
 * NB spaces stay as %20 (the vendored jQuery does NOT convert them to '+').
 * NB #inquiry hashes with a numeric search need inquiry_param() instead.
 */

const PARAM_RBRACKET = /\[\]$/;
const PARAM_NON_OBJECT_TAGS = [
  'Boolean', 'Number', 'String', 'Function', 'Array', 'Date', 'RegExp', 'Error', 'Symbol',
];

function param_is_object(value) {
  // jQuery's toType(value) === 'object'
  if (value == null || (typeof value !== 'object' && typeof value !== 'function')) return false;
  const tag = Object.prototype.toString.call(value).slice(8, -1);
  return PARAM_NON_OBJECT_TAGS.indexOf(tag) === -1;
}

function param_build(prefix, value, add) {
  if (Array.isArray(value)) {
    value.forEach(function (member, index) {
      if (PARAM_RBRACKET.test(prefix)) add(prefix, member);
      else
        param_build(
          prefix + '[' + (typeof member === 'object' && member != null ? index : '') + ']',
          member,
          add,
        );
    });
  } else if (!param_is_object(value)) {
    add(prefix, value);
  } else {
    for (const name in value) param_build(prefix + '[' + name + ']', value[name], add);
  }
}

function param(obj) {
  const parts = [];
  const add = function (key, value) {
    const resolved = typeof value === 'function' ? value() : value;
    parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(resolved == null ? '' : resolved));
  };
  if (obj == null) return '';
  if (Array.isArray(obj)) {
    obj.forEach(function (item) {
      add(item.name, item.value);
    });
  } else {
    for (const key in obj) param_build(key, obj[key], add);
  }
  return parts.join('&');
}

function is_empty(obj) {
  if (!obj) return true;
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) return false;
  }
  return true;
}


/* module: src_js/core/utils.js */
/**
 * Ermac core utilities: base-type extensions, DOM-adjacent helpers,
 * domain data and methods ported from the old wmcore.js.
 */


/**
 * Vendored NLP parser (src_js/third_party/optimade_mpds_nlp.js) defines the window global.
 */
/* global OptimadeNLP */

if (typeof OptimadeNLP === 'undefined') {
  throw new Error('Failed to load OptimadeNLP');
}

const wmutils = OptimadeNLP();

/**
 * Extending base types with the utilities
 */

Array.prototype.extend = function (other_array) {
  other_array.forEach(function (v) {
    this.push(v);
  }, this);
};

String.prototype.startswith = function (prefix) {
  return this.indexOf(prefix) === 0;
};

Number.prototype.count_decimals = function () {
  if (isFinite(this) && Math.floor(this) === this) return 0; // is integer
  var repr = this.toString();
  if (repr.indexOf('.') == -1) return 0;
  return repr.split('.')[1].length || 0;
};

/**
 * Auxiliary methods relevant for DOM
 */

// NB notifications interpolate server-provided text (e.g. data.error):
// besides <script>, drop the other auto-executing vectors (event handler
// attributes, embedded documents) and javascript: URLs, except the one the
// app itself uses in its messages ("please try to reload")
const UNSAFE_ELEMENTS = 'script, iframe, frame, frameset, object, embed, base, meta, link';
const ALLOWED_JS_URL = 'javascript:location.reload()';

wmgui.clean = function (str) {
  const tpl = document.createElement('template');
  tpl.innerHTML = (str || '').bold();
  tpl.content.querySelectorAll(UNSAFE_ELEMENTS).forEach(function (el) {
    el.remove();
  });
  tpl.content.querySelectorAll('*').forEach(function (el) {
    Array.prototype.slice.call(el.attributes).forEach(function (attr) {
      const name = attr.name.toLowerCase();
      const value = attr.value.replace(/[\s\u0000-\u001f]+/g, '').toLowerCase();
      if (
        name.startsWith('on') ||
        ((name === 'href' || name === 'src' || name === 'action' ||
          name === 'formaction' || name === 'xlink:href') &&
          value.startsWith('javascript:') &&
          attr.value.trim() !== ALLOWED_JS_URL)
      )
        el.removeAttribute(attr.name);
    });
  });
  const first = tpl.content.firstElementChild;
  return first ? first.innerHTML : tpl.innerHTML;
};

wmgui.cancel_event = function (evt) {
  evt = evt || window.event;
  if (evt.cancelBubble) evt.cancelBubble = true;
  else {
    if (evt.stopPropagation) evt.stopPropagation();
    if (evt.preventDefault) evt.preventDefault();
  }
};

wmgui.debounce = function (func, wait, immediate) {
  var timeout;

  return function () {
    var context = this,
      args = arguments;
    var later = function () {
      timeout = null;
      if (!immediate) func.apply(context, args);
    };
    var callNow = immediate && !timeout;
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
    if (callNow) func.apply(context, args);
  };
};

wmgui.is_inview = function (element) {
  if (!element) return false;

  var pageTop = window.scrollY,
    pageBottom = pageTop + window.innerHeight,
    elementTop = element.getBoundingClientRect().top + pageTop,
    elementBottom = elementTop + element.offsetHeight;

  return elementTop <= pageBottom && elementBottom >= pageTop;
};

wmgui.show_preloader = function () {
  show($('#preloader'));
};

wmgui.hide_preloader = function () {
  hide($('#preloader'));
};

wmgui.loadCSS = function (href, before, media, attributes) {
  // Arguments:
  // `href` [REQUIRED] is the URL for your CSS file.
  // `before` [OPTIONAL] is the element the script should use as a reference for injecting our stylesheet <link> before
  // By default, loadCSS attempts to inject the link after the last stylesheet or script in the DOM. However, you might desire a more specific location in your document.
  // `media` [OPTIONAL] is the media type or query of the stylesheet. By default it will be 'all'
  // `attributes` [OPTIONAL] is the Object of attribute name/attribute value pairs to set on the stylesheet's DOM Element.
  var ss = document.createElement('link');
  var ref;

  if (before) {
    ref = before;
  } else {
    var refs = (document.body || document.getElementsByTagName('head')[0])
      .childNodes;
    ref = refs[refs.length - 1];
  }

  var sheets = document.styleSheets;
  // Set any of the provided attributes to the stylesheet DOM Element.
  if (attributes) {
    for (var attributeName in attributes) {
      if (attributes.hasOwnProperty(attributeName)) {
        ss.setAttribute(attributeName, attributes[attributeName]);
      }
    }
  }
  ss.rel = 'stylesheet';
  ss.href = href;
  // temporarily set media to something inapplicable to ensure it'll fetch without blocking render
  ss.media = 'only x';

  // wait until body is defined before injecting link. This ensures a non-blocking load in IE11.
  function ready(cb) {
    if (document.body) {
      return cb();
    }
    setTimeout(function () {
      ready(cb);
    });
  }
  // Inject link
  // Note: the ternary preserves the existing behavior of "before" argument, but we could choose to change the argument to "after" in a later release and standardize on ref.nextSibling for all refs
  // Note: `insertBefore` is used instead of `appendChild`, for safety re: http://www.paulirish.com/2011/surefire-dom-element-insertion/
  ready(function () {
    ref.parentNode.insertBefore(ss, before ? ref : ref.nextSibling);
  });

  // A method (exposed on return object for external use) that mimics onload by polling document.styleSheets until it includes the new sheet.
  var onloadcssdefined = function (cb) {
    var resolvedHref = ss.href;
    var i = sheets.length;
    while (i--) {
      if (sheets[i].href === resolvedHref) {
        return cb();
      }
    }
    setTimeout(function () {
      onloadcssdefined(cb);
    });
  };

  function loadCB() {
    if (ss.addEventListener) {
      ss.removeEventListener('load', loadCB);
    }
    ss.media = media || 'all';
  }

  // once loaded, set link's media back to `all` so that the stylesheet applies once it loads
  if (ss.addEventListener) {
    ss.addEventListener('load', loadCB);
  }
  ss.onloadcssdefined = onloadcssdefined;
  onloadcssdefined(loadCB);
  return ss;
};

